import{_ as p,a0 as l,w as o,s as r,ao as d,I as t,x as n,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何在 RHEL 上設置 Linux RAID 1 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 上設置 Linux RAID 1 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 上設置 Linux RAID 1 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 上設置 Linux RAID 1 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20161210 How to Setup Linux RAID 1 Device on RHEL","title":"如何在 RHEL 上設置 Linux RAID 1","tag":"201702","desc":""},"relativePath":"201702/20161210 How to Setup Linux RAID 1 Device on RHEL.md","filePath":"[post].md"}'),u={name:"201702/20161210 How to Setup Linux RAID 1 Device on RHEL.md"};function m(x,s,c,h,L,D){const a=l("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="如何在-rhel-上設置-linux-raid-1" tabindex="-1">如何在 RHEL 上設置 Linux RAID 1 <a class="header-anchor" href="#如何在-rhel-上設置-linux-raid-1" aria-label="Permalink to “如何在 RHEL 上設置 Linux RAID 1”">​</a></h1><h3 id="設置-linux-raid-1" tabindex="-1">設置 Linux RAID 1 <a class="header-anchor" href="#設置-linux-raid-1" aria-label="Permalink to “設置 Linux RAID 1”">​</a></h3><p>配置 LINUX RAID 1 非常重要，因為它提供了冗餘性。</p><p>RAID 分區擁有高級功能，如冗餘和更好的性能。所以讓我們來説下如何實現 RAID，以及讓我們來看看不同類型的 RAID：</p><ul><li>RAID 0（條帶）：磁盤組合在一起，形成一個更大的驅動器。這以可用性為代價提供了更好的性能。如果 RAID 中的任何一塊磁盤出現故障，則整個磁盤集將無法使用。最少需要兩塊磁盤。</li><li>RAID 1（鏡像）：磁盤從一個複製到另一個，提供了冗餘。如果一塊磁盤發生故障，則另一塊磁盤接管，它有另外一份原始磁盤的數據的完整副本。其缺點是寫入時間慢。最少需要兩塊磁盤。</li><li>RAID 5（帶奇偶校驗的條帶）：磁盤類似於 RAID 0，並且連接在一起以形成一個大型驅動器。這裏的區別是，25％ 的磁盤用於奇偶校驗位，這允許在單個磁盤發生故障時可以恢復磁盤。最少需要三塊盤。</li></ul><p>讓我們繼續進行 Linux RAID 1 配置。</p><p>安裝 Linux RAID 1 的要求：</p><p>1、系統中應該安裝了 mdam，請用下面的命令確認。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@rhel1 ~]# rpm -qa | grep -i mdadm</span></span>
<span class="line"><span>mdadm-3.2.2-9.el6.x86_64</span></span>
<span class="line"><span>[root@rhel1 ~]#</span></span></code></pre></div><p>2、 系統應該連接了 2 塊磁盤。</p><p>創建兩個分區，一個磁盤一個分區（sdc、sdd），每個分區佔據整塊磁盤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Disk /dev/sdc: 1073 MB, 1073741824 bytes</span></span>
<span class="line"><span>255 heads, 63 sectors/track, 130 cylinders</span></span>
<span class="line"><span>Units = cylinders of 16065 * 512 = 8225280 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disk identifier: 0x67cc8cfb</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device Boot Start End Blocks Id System</span></span>
<span class="line"><span>/dev/sdc1 1 130 1044193+ 83 Linux</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sdd: 1073 MB, 1073741824 bytes</span></span>
<span class="line"><span>255 heads, 63 sectors/track, 130 cylinders</span></span>
<span class="line"><span>Units = cylinders of 16065 * 512 = 8225280 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disk identifier: 0x0294382b</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device Boot Start End Blocks Id System</span></span>
<span class="line"><span>/dev/sdd1 1 130 1044193+ 83 Linux</span></span></code></pre></div><hr><p>作者簡介：</p><p>大家好！我是 Manmohan Mirkar。我很高興見到你們！我在 10 多年前開始使用 Linux，我從來沒有想過我會到今天這個地步。我的激情是幫助你們獲取 Linux 知識。謝謝閲讀！</p><hr>`,16)),t("p",null,[s[1]||(s[1]=n("via: ",-1)),i(a,{href:"http://www.linuxroutes.com/linux-raid-1/"},{default:e(()=>[...s[0]||(s[0]=[n("http://www.linuxroutes.com/linux-raid-1/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=n("作者：",-1)),i(a,{href:"http://www.linuxroutes.com/author/admin/"},{default:e(()=>[...s[2]||(s[2]=[n("Manmohan Mirkar",-1)])]),_:1}),s[6]||(s[6]=n(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[3]||(s[3]=[n("geekpi",-1)])]),_:1}),s[7]||(s[7]=n(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[8]||(s[8]=[n("LCTT",-1)])]),_:1}),s[11]||(s[11]=n(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[9]||(s[9]=[n("Linux中國",-1)])]),_:1}),s[12]||(s[12]=n(" 榮譽推出",-1))])])}const f=p(u,[["render",m]]);export{b as __pageData,f as default};
